def fig_fire():
    X=lambda t:50+t*2.7;Y=lambda v:170-v*1.4
    o=L(50,20,50,170)+L(50,170,320,170)
    ts=range(0,101,4)
    o+='<path d="M'+' L'.join(f'{X(t):.1f} {Y(sm(t)):.1f}' for t in ts)+'" class="lna"/>'
    o+='<path d="M'+' L'.join(f'{X(t):.1f} {Y(ht(t)):.1f}' for t in ts)+'" class="ln"/>'
    for t,c,l in ((22,'ac','түтін хабарлағышы'),(56,'','жылу хабарлағышы')):
        o+=f'<line x1="{X(t)}" y1="{Y(sm(t) if c else ht(t))}" x2="{X(t)}" y2="170" class="ln dash"/>'+(TR(X(t)+30,186,l,'t-s '+c) if c else TL(X(t)-30,186,l,'t-s'))
    o+=TL(58,28,'белгінің күші','t-s t-b')+TL(X(38),Y(90),'түтін','t-s ac')+TL(X(74),Y(66),'жылу','t-s')+TL(180,206,'уақыт →','t-s mu')
    return S(340,214,o,'Өрттің дамуы кезінде түтін мен жылудың өсуі')
